  it('logado, a etapa do nome não aparece', async () => {
    localStorage.setItem('token', 'qualquer');
    renderBooking();

    expect(screen.queryByLabelText('Como podemos te chamar?')).toBeNull();
    expect(await screen.findByText('Carlos Barbeiro')).toBeTruthy();
  });
});

